import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.CMX7UUIo.js";const c=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"en/crops/wheat/index.md","filePath":"en/crops/wheat/index.md"}'),n={name:"en/crops/wheat/index.md"};function o(s,e,l,d,h,g){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="wheat" tabindex="-1">Wheat <a class="header-anchor" href="#wheat" aria-label="Permalink to “Wheat”">​</a></h1><p><a href="https://en.wikipedia.org/wiki/Wheat" target="_blank" rel="noreferrer">Wheat</a> (scientific name: Triticum aestivum) is a species of annual or biennial grass in the Poaceae family, with flowering and fruiting occurring from May to July. It is one of the three most important grain crops globally (alongside rice and corn).</p><h2 id="plant-characteristics" tabindex="-1">Plant Characteristics <a class="header-anchor" href="#plant-characteristics" aria-label="Permalink to “Plant Characteristics”">​</a></h2><ul><li><p><strong>Structure</strong>: Consists of roots, stems, leaves, ears, and seeds (grains). The stem is erect, hollow, and jointed; the spike is usually upright, often with awns (the long slender spines on the ear).</p></li><li><p><strong>Growth Environment</strong>: Wheat has strong adaptability but grows best in temperate regions. Based on the planting season, it is mainly divided into:</p><ul><li><strong><a href="https://en.wikipedia.org/wiki/Winter_wheat" target="_blank" rel="noreferrer">Winter Wheat</a></strong>: Planted in autumn, undergoes winter dormancy (vernalization), and is harvested in the following summer.</li><li><strong><a href="https://en.wikipedia.org/wiki/Spring_wheat" target="_blank" rel="noreferrer">Spring Wheat</a></strong>: Planted in spring and harvested in the same year in autumn.</li></ul></li></ul><h2 id="value" tabindex="-1">Value <a class="header-anchor" href="#value" aria-label="Permalink to “Value”">​</a></h2><p>As an important staple food in China, wheat mainly provides <strong>carbohydrates</strong>, some <strong>protein</strong>, B vitamins, and <strong>minerals</strong>. Its core function is providing stable energy. Its unique value lies in its <strong>gluten protein system</strong>. This makes it more suitable than many grains for making bread, noodles, steamed buns, cookies, cakes, and other foods. Among grains, wheat has strong &quot;plasticity&quot; and &quot;product diversity.&quot; Because of this characteristic, wheat can be classified as strong gluten, medium gluten, or weak gluten, corresponding to different food uses.</p><p>Economically, wheat is a bulk basic agricultural product, connecting the entire industrial chain including <strong>planting</strong>, <strong>storage</strong>, <strong>logistics</strong>, <strong>milling</strong>, <strong>food processing</strong>, <strong>feed</strong>, and <strong>by-product utilization</strong>. It not only produces flour, but also bran, middlings, and germ, all of which have value.</p><h2 id="production-regions" tabindex="-1">Production Regions <a class="header-anchor" href="#production-regions" aria-label="Permalink to “Production Regions”">​</a></h2><p>China has a wide distribution of wheat, with diverse geographical and climatic environments, suitable for planting both <a href="https://en.wikipedia.org/wiki/Winter_wheat" target="_blank" rel="noreferrer">winter wheat</a> and <a href="https://en.wikipedia.org/wiki/Spring_wheat" target="_blank" rel="noreferrer">spring wheat</a>.</p><p>The main wheat-producing regions primarily plant winter wheat, with planting areas concentrated in <a href="https://en.wikipedia.org/wiki/Henan" target="_blank" rel="noreferrer">Henan</a>, <a href="https://en.wikipedia.org/wiki/Shandong" target="_blank" rel="noreferrer">Shandong</a>, <a href="https://en.wikipedia.org/wiki/Anhui" target="_blank" rel="noreferrer">Anhui</a>, <a href="https://en.wikipedia.org/wiki/Jiangsu" target="_blank" rel="noreferrer">Jiangsu</a>, <a href="https://en.wikipedia.org/wiki/Hebei" target="_blank" rel="noreferrer">Hebei</a>, <a href="https://en.wikipedia.org/wiki/Sichuan" target="_blank" rel="noreferrer">Sichuan</a>, <a href="https://en.wikipedia.org/wiki/Hubei" target="_blank" rel="noreferrer">Hubei</a>, <a href="https://en.wikipedia.org/wiki/Shaanxi" target="_blank" rel="noreferrer">Shaanxi</a>, <a href="https://en.wikipedia.org/wiki/Xinjiang" target="_blank" rel="noreferrer">Xinjiang</a>, <a href="https://en.wikipedia.org/wiki/Shanxi" target="_blank" rel="noreferrer">Shanxi</a>, and <a href="https://en.wikipedia.org/wiki/Gansu" target="_blank" rel="noreferrer">Gansu</a>, accounting for about 95% of the total winter wheat area in China. The main spring wheat-producing regions include <a href="https://en.wikipedia.org/wiki/Inner_Mongolia" target="_blank" rel="noreferrer">Inner Mongolia</a>, Xinjiang, Gansu, <a href="https://en.wikipedia.org/wiki/Qinghai" target="_blank" rel="noreferrer">Qinghai</a>, <a href="https://en.wikipedia.org/wiki/Heilongjiang" target="_blank" rel="noreferrer">Heilongjiang</a>, <a href="https://en.wikipedia.org/wiki/Ningxia" target="_blank" rel="noreferrer">Ningxia</a>, <a href="https://en.wikipedia.org/wiki/Tianjin" target="_blank" rel="noreferrer">Tianjin</a>, Hebei, and <a href="https://en.wikipedia.org/wiki/Tibet" target="_blank" rel="noreferrer">Tibet</a>, with Inner Mongolia having the largest area and Tibet having the highest yield per unit area, followed by Xinjiang.</p><h2 id="production" tabindex="-1">Production <a class="header-anchor" href="#production" aria-label="Permalink to “Production”">​</a></h2><p>Over the past five years, China&#39;s wheat production has successfully shifted to a yield-per-unit improvement model driven by technology, after fluctuations in 2023 when area expanded but yields were affected by disasters. It has maintained stable production at 140 million tons for two consecutive years, with production efficiency reaching historical peaks.</p><table tabindex="0"><thead><tr><th>Year</th><th>Sowing Area (thousand hectares)</th><th>Total Production (10,000 tons)</th><th>Yield (kg/hectare)</th></tr></thead><tbody><tr><td>2025</td><td>23,581.8</td><td>14,007.2</td><td><strong>5,939.8</strong></td></tr><tr><td>2024</td><td>23,587.4</td><td><strong>14,009.9</strong></td><td>5,939.6</td></tr><tr><td>2023</td><td><strong>23,627.2</strong></td><td>13,659.0</td><td>5,781.0</td></tr><tr><td>2022</td><td>23,518.5</td><td>13,772.3</td><td>5,856.0</td></tr><tr><td>2021</td><td>23,568.4</td><td>13,694.6</td><td>5,810.6</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Source: <a href="https://www.stats.gov.cn/" target="_blank" rel="noreferrer">National Bureau of Statistics</a></p></div>',14)])])}const u=t(n,[["render",o]]);export{c as __pageData,u as default};
